//! Parity of the approximate GPs of phase 10c with BoTorch, from the
//! fixtures in `tests/fixtures/10c_approximate/*.json` (generated by
//! `scripts/generate_fixtures.py --phase 10c-approximate`):
//!
//! * `allocators.json`: BoTorch's `_pivoted_cholesky_init` (the selected
//!   points, exactly) and the `ExpectedImprovementQualityFunction` scores;
//! * `models.json`: `SingleTaskVariationalGP` cases: the inducing points
//!   allocated at construction, parameter names, sizes, bounds and initial
//!   values, the ELBO terms and gradient at random parameters, and
//!   posteriors (`q = 1` batches and joint sets) with their input
//!   gradients;
//! * `fits.json`: fits compared with BoTorch's outcomes on 64 twins (the
//!   two-stage procedure of `docs/fitting.md`).
//!
//! Run with `--nocapture` to print the error tables.

#![allow(clippy::needless_range_loop)]

mod common;

use botorch_core::constraints::{GreaterThan, ParameterTransform};
use botorch_core::fit::{FitOptions, Fittable};
use botorch_core::models::approximate_gp::{
    ElboFit, SingleTaskVariationalGP, SingleTaskVariationalGPOptions, VariationalLikelihood,
    VariationalMean, VARIATIONAL_JITTER,
};
use botorch_core::models::gp::{
    get_gaussian_likelihood_with_lognormal_prior, ConstantMeanSpec, GaussianLikelihoodSpec,
    MIN_INFERRED_NOISE_LEVEL,
};
use botorch_core::models::inducing_point_allocators::{
    expected_improvement_quality, pivoted_cholesky_init, unit_quality,
};
use botorch_core::transforms::input::{ChainedInputTransform, InputTransformStep};
use botorch_core::transforms::{Normalize, Standardize};
use botorch_core::{Matrix, Model, Prior, Vector};
use common::{fixture_dir, matrix, Report};
use serde::Deserialize;
use serde_json::Value;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;

fn load<T: for<'de> Deserialize<'de>>(name: &str) -> T {
    let path = fixture_dir().join("10c_approximate").join(name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap()
}

/// Normwise relative error of gradients (relative to the largest component).
fn grad_err(actual: &[f64], expected: &[f64]) -> f64 {
    assert_eq!(actual.len(), expected.len());
    let scale = expected.iter().fold(0.0f64, |m, v| m.max(v.abs())).max(1e-300);
    actual
        .iter()
        .zip(expected)
        .map(|(a, e)| (a - e).abs() / scale)
        .fold(0.0, f64::max)
}

// ---------------------------------------------------------------------------
// Allocators
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct PivotedCase {
    kernel_matrix: Vec<Vec<f64>>,
    max_length: usize,
    quality: Vec<f64>,
    selected_points: Vec<Vec<f64>>,
    x: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct EiCase {
    maximize: bool,
    mean: Vec<f64>,
    variance: Vec<f64>,
    quality: Vec<f64>,
}

#[derive(Deserialize)]
struct Allocators {
    pivoted: Vec<PivotedCase>,
    ei_quality: Vec<EiCase>,
}

#[test]
fn allocators_match_botorch() {
    let fx: Allocators = load("allocators.json");
    let mut report = Report::default();
    for (i, c) in fx.pivoted.iter().enumerate() {
        let k = matrix(&c.kernel_matrix);
        let sel = pivoted_cholesky_init(&k, c.max_length, &c.quality, 1e-6).unwrap();
        // Points, not indices: duplicated inputs are interchangeable.
        let pts: Vec<&Vec<f64>> = sel.iter().map(|&j| &c.x[j]).collect();
        let same = pts.len() == c.selected_points.len()
            && pts.iter().zip(&c.selected_points).all(|(a, b)| *a == b);
        report.check(
            &format!("pivoted {i}"),
            "selected points",
            if same { 0.0 } else { 1.0 },
            0.0,
        );
    }
    for (i, c) in fx.ei_quality.iter().enumerate() {
        let q = expected_improvement_quality(&c.mean, &c.variance, c.maximize).unwrap();
        report.check_slices(&format!("ei {i}"), "EI quality", &q, &c.quality, VALUE_TOL);
    }
    report.finish("10c allocators");
}

// ---------------------------------------------------------------------------
// Models
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct ElboEval {
    num_data: f64,
    beta: f64,
    terms: [f64; 3],
    value: f64,
    grad: Vec<f64>,
}

#[derive(Deserialize)]
struct Evaluation {
    raw: Vec<f64>,
    elbo: Vec<ElboEval>,
    x_test: Vec<Vec<f64>>,
    q1_mean: Vec<f64>,
    q1_variance: Vec<f64>,
    q1_grad: Vec<f64>,
    joint_mean: Vec<f64>,
    joint_covariance: Vec<Vec<f64>>,
    joint_covariance_noise: Vec<Vec<f64>>,
    joint_grad: Vec<f64>,
    weights_mean: Vec<f64>,
    weights_cov: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct ModelCase {
    name: String,
    m: usize,
    learn_inducing_points: bool,
    kernel: Value,
    mean: String,
    likelihood: String,
    input_tf: bool,
    train_x: Vec<Vec<f64>>,
    train_x_tf: Vec<Vec<f64>>,
    train_y_tf: Vec<Vec<f64>>,
    inducing: Vec<Vec<f64>>,
    names: Vec<String>,
    sizes: Vec<usize>,
    lower: Vec<Value>,
    upper: Vec<Value>,
    raw_default: Vec<f64>,
    outcome_means: Option<Vec<f64>>,
    outcome_stdvs: Option<Vec<f64>>,
    #[serde(default)]
    evaluations: Vec<Evaluation>,
    #[serde(default)]
    twins: Vec<Twin>,
}

#[derive(Deserialize)]
struct Twin {
    x: Vec<Vec<f64>>,
    raw0: Vec<f64>,
    inducing0: Vec<Vec<f64>>,
    loss: f64,
    attempts: usize,
}

fn softplus_noise() -> GaussianLikelihoodSpec {
    GaussianLikelihoodSpec {
        noise_prior: None,
        noise_constraint: GreaterThan::new(
            MIN_INFERRED_NOISE_LEVEL,
            Some(ParameterTransform::Softplus),
            None,
        )
        .rounded_to_f32()
        .into(),
    }
}

fn options_of(c: &ModelCase) -> SingleTaskVariationalGPOptions {
    let d = c.train_x[0].len();
    let noise = match c.likelihood.as_str() {
        "default" if c.m == 1 => get_gaussian_likelihood_with_lognormal_prior(),
        "default" | "gaussian" => softplus_noise(),
        "gamma" => GaussianLikelihoodSpec {
            noise_prior: Some(Prior::gamma(1.1, 0.05).unwrap().rounded_to_f32()),
            ..softplus_noise()
        },
        other => panic!("unknown likelihood {other}"),
    };
    let likelihood = if c.m == 1 {
        VariationalLikelihood::Gaussian(noise)
    } else {
        VariationalLikelihood::Multitask(noise)
    };
    let mean_module = match c.mean.as_str() {
        "default" => VariationalMean::Constant(ConstantMeanSpec::default()),
        "prior" => VariationalMean::Constant(ConstantMeanSpec {
            prior: Some(Prior::normal(0.1, 2.0).unwrap().rounded_to_f32()),
            constraint: None,
        }),
        "zero" => VariationalMean::Zero,
        other => panic!("unknown mean {other}"),
    };
    let input_transform = c.input_tf.then(|| {
        let mut chain = ChainedInputTransform::new(vec![InputTransformStep::Normalize(
            Normalize::new(d),
        )])
        .unwrap();
        chain.fit(&matrix(&c.train_x)).unwrap();
        chain
    });
    let outcome_transform = c.outcome_means.as_ref().map(|m| {
        Standardize::fitted(m.clone(), c.outcome_stdvs.clone().unwrap(), 1e-8).unwrap()
    });
    SingleTaskVariationalGPOptions {
        covar_module: common::kernel_spec::node(&c.kernel),
        covar_batched: c.m > 1,
        mean_module,
        mean_batched: c.m > 1,
        likelihood,
        learn_inducing_points: c.learn_inducing_points,
        jitter: VARIATIONAL_JITTER,
        input_transform,
        outcome_transform,
    }
}

fn build(c: &ModelCase, x_tf: &Matrix, inducing: &Matrix, raw: Option<Vec<f64>>) -> SingleTaskVariationalGP {
    let d = c.train_x[0].len();
    SingleTaskVariationalGP::new(
        x_tf.clone(),
        Some(matrix(&c.train_y_tf)),
        inducing.clone(),
        c.m,
        d,
        raw,
        options_of(c),
    )
    .unwrap()
}

/// BoTorch's point-major `q × m` flattening to botorch_rs's output-major
/// order (and back for interleaved covariances).
fn point_major_index(q: usize, m: usize, k: usize) -> usize {
    // output-major index k = t q + p -> point-major p m + t
    let (t, p) = (k / q, k % q);
    p * m + t
}

#[test]
fn models_match_botorch() {
    let cases: Vec<ModelCase> = load("models.json");
    let mut report = Report::default();
    for c in &cases {
        let name = c.name.as_str();
        let x_tf = matrix(&c.train_x_tf);
        let z = matrix(&c.inducing);
        let mut model = build(c, &x_tf, &z, None);
        // Transformed training inputs (input transform fitted in Rust).
        if let Some(chain) = &model.options().input_transform {
            let xt = chain.transform(&matrix(&c.train_x)).unwrap();
            report.check_slices(
                name,
                "transformed train_X",
                xt.as_slice(),
                x_tf.as_slice(),
                VALUE_TOL,
            );
        }
        // The greedy allocation (GreedyVarianceReduction with the initial
        // kernel of the first output).
        if c.name != "inducing_train" {
            let k = model.kernel(0).unwrap().covariance_symmetric(&x_tf).unwrap();
            let n = x_tf.nrows();
            let sel = pivoted_cholesky_init(&k, z.nrows(), &unit_quality(n), 1e-6).unwrap();
            let zr = Matrix::from_fn(sel.len(), x_tf.ncols(), |i, j| x_tf[(sel[i], j)]);
            let err = if zr.shape() == z.shape() { (&zr - &z).amax() } else { 1.0 };
            report.check(name, "allocated inducing points", err, 0.0);
        }
        // Names, sizes, bounds, defaults.
        let names: Vec<(String, usize)> = model.parameter_names();
        let ok = names.len() == c.names.len()
            && names
                .iter()
                .zip(c.names.iter().zip(&c.sizes))
                .all(|((n, s), (en, es))| n == en && s == es);
        report.check(name, "parameter names and sizes", if ok { 0.0 } else { 1.0 }, 0.0);
        let bounds = model.raw_parameter_bounds();
        let lo: Vec<f64> = c.lower.iter().map(common::kernel_spec::num).collect();
        let hi: Vec<f64> = c.upper.iter().map(common::kernel_spec::num).collect();
        let bok = bounds.iter().zip(lo.iter().zip(&hi)).all(|(b, (l, h))| b.0 == *l && b.1 == *h);
        report.check(name, "bounds", if bok { 0.0 } else { 1.0 }, 0.0);
        report.check_slices(
            name,
            "default raw parameters",
            model.raw_parameters(),
            &c.raw_default,
            0.0,
        );
        let m = c.m;
        for ev in &c.evaluations {
            model.set_raw_parameters(&ev.raw).unwrap();
            for e in &ev.elbo {
                let (t, g) = model.elbo_value_and_grad(&ev.raw, e.num_data, e.beta).unwrap();
                report.check_slices(
                    name,
                    "ELBO terms",
                    &[t.log_likelihood, t.kl_divergence, t.log_prior],
                    &e.terms,
                    VALUE_TOL,
                );
                report.check_slices(name, "ELBO", &[t.value()], &[e.value], VALUE_TOL);
                report.check(name, "ELBO gradient", grad_err(&g, &e.grad), GRAD_TOL);
            }
            let xt = matrix(&ev.x_test);
            let q = xt.nrows();
            // q = 1 batches.
            let pp = model.point_posteriors(&xt).unwrap();
            let mut means = Vec::new();
            let mut vars = Vec::new();
            let mut grads = Vec::new();
            for i in 0..q {
                let g = model.point_posterior_with_grad(&xt.row(i).iter().copied().collect::<Vec<_>>()).unwrap();
                for t in 0..m {
                    means.push(pp.mean[(i, t)]);
                    vars.push(pp.covariance[(i, t * m + t)]);
                }
                for k in 0..xt.ncols() {
                    let s: f64 = (0..m).map(|t| g.dmean[k][t] + g.dcov[k][(t, t)]).sum();
                    grads.push(s);
                }
            }
            report.check_slices(name, "q=1 posterior mean", &means, &ev.q1_mean, VALUE_TOL);
            report.check_slices(name, "q=1 posterior variance", &vars, &ev.q1_variance, VALUE_TOL);
            report.check(name, "q=1 d(mean + variance)/dx", grad_err(&grads, &ev.q1_grad), GRAD_TOL);
            // Joint posterior (BoTorch: point-major mean, interleaved
            // covariance).
            let qm = q * m;
            let perm: Vec<usize> = (0..qm).map(|k| point_major_index(q, m, k)).collect();
            for (noise, expected) in [(false, &ev.joint_covariance), (true, &ev.joint_covariance_noise)] {
                let p = model.posterior(&xt, noise).unwrap();
                let mean: Vec<f64> = (0..qm).map(|k| p.mean[k]).collect();
                let em: Vec<f64> = perm.iter().map(|&j| ev.joint_mean[j]).collect();
                if !noise {
                    report.check_slices(name, "joint posterior mean", &mean, &em, VALUE_TOL);
                }
                let cov: Vec<f64> = (0..qm).flat_map(|a| (0..qm).map(move |b| (a, b))).map(|(a, b)| p.covariance[(a, b)]).collect();
                let ec: Vec<f64> = (0..qm)
                    .flat_map(|a| (0..qm).map(move |b| (a, b)))
                    .map(|(a, b)| expected[perm[a]][perm[b]])
                    .collect();
                let label = if noise { "joint covariance with noise" } else { "joint covariance" };
                report.check_slices(name, label, &cov, &ec, VALUE_TOL);
            }
            let ma = Vector::from_fn(qm, |k, _| ev.weights_mean[perm[k]]);
            let ca = Matrix::from_fn(qm, qm, |a, b| ev.weights_cov[perm[a]][perm[b]]);
            let vjp = model.joint_posterior_vjp(&xt, 0..q, &ma, &ca).unwrap();
            let g: Vec<f64> = (0..q).flat_map(|i| (0..xt.ncols()).map(move |k| (i, k))).map(|(i, k)| vjp[(i, k)]).collect();
            report.check(name, "joint d(weighted sum)/dx", grad_err(&g, &ev.joint_grad), GRAD_TOL);
            // Forward mode agrees with the reverse mode.
            let fwd = model.joint_posterior_with_grad(&xt).unwrap();
            let gf: Vec<f64> = (0..q * xt.ncols())
                .map(|j| ma.dot(&fwd.dmean[j]) + ca.component_mul(&fwd.dcov[j]).sum())
                .collect();
            report.check(name, "joint d/dx (forward mode)", grad_err(&gf, &ev.joint_grad), GRAD_TOL);
        }
    }
    report.finish("10c models");
}

// ---------------------------------------------------------------------------
// Fits
// ---------------------------------------------------------------------------

#[test]
fn fits_match_botorch() {
    let cases: Vec<ModelCase> = load("fits.json");
    let mut report = Report::default();
    for c in &cases {
        let fit = |t: usize| -> (f64, usize) {
            let tw = &c.twins[t];
            let x = matrix(&tw.x);
            let model = build(c, &x, &matrix(&tw.inducing0), Some(tw.raw0.clone()));
            let mut f = ElboFit {
                model,
                num_data: c.train_x.len() as f64,
                beta: 1.0,
            };
            match f.fit_mll(FitOptions::default()) {
                Ok(r) => (r.loss, r.attempts),
                Err(_) => (f64::INFINITY, 6),
            }
        };
        let bt: Vec<(f64, usize)> = c.twins.iter().map(|t| (t.loss, t.attempts)).collect();
        let own = fit(0);
        common::compare_fits_and_first_attempts(&mut report, &c.name, "fit", &bt, &[], own, &mut |t| fit(t));
    }
    report.finish("10c fits");
}
